const input = $input.first()?.json ?? {};
const raw = input.body && input.headers ? input.body : input;
const source = raw.source ?? {};
const mode = raw.mode == null ? 'generate' : String(raw.mode);
const requestId = String(raw.requestId ?? ('manual-' + $execution.id));
const triggerSource = String(raw.triggerSource ?? 'manual') + (mode === 'improve-existing' ? ':improve-existing' : '');
const existingLineTitle = String(raw.existingLineTitle ?? '').trim();
const existingLineDescription = String(raw.existingLineDescription ?? '').trim();
const missingTitle = !existingLineTitle;
const missingDescription = !existingLineDescription;
const startedAt = new Date().toISOString();
const validSource = Boolean(source.id && source.revision && source.slug && source.title && source.category);
const valid = validSource && (
  mode === 'improve-existing'
    ? Boolean(existingLineTitle && existingLineDescription && !Object.hasOwn(raw, 'body'))
    : mode === 'generate' && Boolean(raw.body)
);
if (!valid) {
  return [{json:{
    requestId, requestKey:requestId, triggerSource, mode, source,
    status:'error', stage:'input', repairAttempt:0, startedAt,
    finishedAt:new Date().toISOString(), elapsedMs:0,
    missingTitle, missingDescription, errorCategory:'invalid-input',
    errorMessage:'ข้อมูลสำหรับสร้างหรือปรับปรุง LINE ไม่ครบ',
    lineTitle:existingLineTitle || null,
    lineDescription:existingLineDescription || null
  }}];
}
return [{json:{
  requestId, requestKey:requestId, triggerSource, mode, source,
  title:String(raw.title ?? source.title),
  ...(mode === 'generate' ? {body:String(raw.body).slice(0, 8000)} : {}),
  category:String(raw.category ?? source.category),
  existingLineTitle:existingLineTitle || null,
  existingLineDescription:existingLineDescription || null,
  missingTitle, missingDescription,
  status:mode === 'improve-existing' ? 'running' : (!missingTitle && !missingDescription ? 'skipped-existing' : 'running'),
  stage:mode === 'improve-existing' ? 'improve' : (!missingTitle && !missingDescription ? 'skip' : 'generate'),
  repairAttempt:0, startedAt
}}];

const data=$json;
const finishedAt=new Date().toISOString();
const elapsedMs=Math.max(0,Date.now()-(Date.parse(data.startedAt)||Date.now()));
return [{json:{...data,status:'generated',stage:'done',finishedAt,elapsedMs,errorCategory:null,errorMessage:null}}];

const data=$json;
const finishedAt=new Date().toISOString();
const elapsedMs=Math.max(0,Date.now()-(Date.parse(data.startedAt)||Date.now()));
return [{json:{...data,status:'error',stage:data.stage || 'error',finishedAt,elapsedMs,errorCategory:data.errorCategory || 'line-copy-failed',errorMessage:data.errorMessage || 'LINE copy generation failed'}}];

const data=$json;
const finishedAt=new Date().toISOString();
const elapsedMs=Math.max(0,Date.now()-(Date.parse(data.startedAt)||Date.now()));
return [{json:{...data,status:'skipped-existing',stage:'skipped',finishedAt,elapsedMs,lineTitle:data.existingLineTitle,lineDescription:data.existingLineDescription,errorCategory:null,errorMessage:null}}];

