const base=$('เตรียมงาน LINE').item.json;
const responses=[
  $('Ollama · Candidate A').item.json,
  $('Ollama · Candidate B').item.json,
  $('Ollama · Candidate C').item.json
];
const segmenter=new Intl.Segmenter('th',{granularity:'grapheme'});
const count=(v)=>[...segmenter.segment(String(v??'').trim())].length;
const clean=(v)=>String(v??'').replace(/\\n/g,' ').replace(/\\\"/g,'"').replace(/\s+/g,' ').trim();
const banned=['รับประกันผลตอบแทน','รับประกันกำไร','รับประกันอนุมัติ','รับประกันเคลมผ่าน','รับประกันความคุ้มครอง','การันตีผลตอบแทน','การันตีกำไร','การันตีอนุมัติ','การันตีเคลมผ่าน','การันตีความคุ้มครอง','รับรองผลตอบแทน','รับรองกำไร','รับรองอนุมัติ','รับรองเคลมผ่าน','รับรองความคุ้มครอง','ไม่ขาดทุน','ไม่มีความเสี่ยง','ผลตอบแทนแน่นอน','อนุมัติแน่นอน','เคลมผ่านแน่นอน','คุ้มครองทุกกรณี','จ่ายแน่นอน','ห้ามพลาด','ด่วน','ก่อนสาย','ความลับ','ช็อก'];
const marketing=['ทัก LINE','LINE Official Account','CCPun','สนใจคุย','มาวางแผน'];
const directIdentifier=/(?:^|\D)0\d{8,9}(?:\D|$)|[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}|(?:^|\D)\d{13}(?:\D|$)/i;
const danglingEnding=/(?:[,;:/\-–—]|(?:\s|^)(?:และ|หรือ|ที่|ซึ่ง|เพื่อ|โดย|กับ|จาก|ของ|ใน|ให้|ว่า|เมื่อ|เพราะ|รวมถึง|ไม่ว่าจะเป็น|ก็คือ|ดังนี้))$/u;
const safe=(v)=>v&&!banned.some(x=>v.includes(x))&&!marketing.some(x=>v.includes(x))&&!directIdentifier.test(v)&&!danglingEnding.test(v);
const uniq=(a)=>[...new Set(a.map(clean).filter(Boolean))];

function extract(response,key){
  if(response?.error) return '';
  const content=String(response?.message?.content??'');
  try{
    const parsed=JSON.parse(content);
    return String(parsed?.[key]??'').trim();
  }catch{}
  const re=new RegExp('"'+key+'"\\s*:\\s*"([^"]*)');
  return String(content.match(re)?.[1]??'').trim();
}

const modelTitles=[];
const modelDescriptions=[];
let modelErrors=0;
for(const response of responses){
  if(response?.error){modelErrors++;continue;}
  const title=extract(response,'lineTitle');
  const description=extract(response,'lineDescription');
  if(base.missingTitle&&title) modelTitles.push(title);
  if(base.missingDescription&&description&&response?.done_reason!=='length') modelDescriptions.push(description);
  if(!title&&!description) modelErrors++;
}

const body=String(base.body??'');
const bodyLines=body.split(/\n+/).map(clean).filter(Boolean);
const extractiveTitles=bodyLines.filter((value)=>{
  const n=count(value);
  return n>=24&&n<=60&&/[?？]$/.test(value)&&safe(value);
});

const extractiveChunks=body
  .split(/\n{2,}|(?<=[?!。！？])\s*/u)
  .map(clean)
  .filter(Boolean);
const extractiveDescriptions=extractiveChunks.filter((value)=>{
  const n=count(value);
  return n>=50&&n<=90&&safe(value);
});

const allTitles=uniq([...modelTitles,...extractiveTitles]);
const allDescriptions=uniq([...modelDescriptions,...extractiveDescriptions]);
const validTitleCandidates=base.missingTitle?allTitles.filter(v=>safe(v)&&count(v)>=24&&count(v)<=60):[];
const validDescriptionCandidates=base.missingDescription?allDescriptions.filter(v=>safe(v)&&count(v)>=50&&count(v)<=90):[];

const titleScore=(value)=>Math.abs(count(value)-40)+(value.includes(base.category)?-5:0);
const descriptionScore=(value)=>Math.abs(count(value)-68)+(value.includes(base.category)?-6:0)+(value.startsWith('ดีขึ้นมาหน่อย')?15:0)+(value.startsWith('เป็นคำถาม')?10:0);
validTitleCandidates.sort((a,b)=>titleScore(a)-titleScore(b));
validDescriptionCandidates.sort((a,b)=>descriptionScore(a)-descriptionScore(b));

const issues=[];
if(base.missingTitle&&!validTitleCandidates.length) issues.push('lineTitle:no-valid-candidate');
if(base.missingDescription&&!validDescriptionCandidates.length) issues.push('lineDescription:no-valid-candidate');

return [{json:{
  ...base,
  state:issues.length?'error':'select',
  stage:'candidate-filter',
  repairAttempt:0,
  validTitleCandidates:validTitleCandidates.slice(0,8),
  validDescriptionCandidates:validDescriptionCandidates.slice(0,8),
  candidateStats:{
    modelTitleGenerated:uniq(modelTitles).length,
    modelDescriptionGenerated:uniq(modelDescriptions).length,
    extractiveTitleGenerated:uniq(extractiveTitles).length,
    extractiveDescriptionGenerated:uniq(extractiveDescriptions).length,
    titleValid:validTitleCandidates.length,
    descriptionValid:validDescriptionCandidates.length,
    modelErrors
  },
  issues,
  errorCategory:issues.length?'model-output-invalid':null,
  errorMessage:issues.length?'No safe complete candidate passed the n8n LINE size contract':null
}}];

