const data=$('มี Candidate ผ่าน?').item.json;
const content=String($json?.message?.content??'').trim();
const readIndex=(pattern)=>{
  const m=content.match(pattern);
  return m?Number(m[1]):null;
};
let titleIndex=data.missingTitle?readIndex(/TITLE_INDEX\s*=\s*(\d+)/i):null;
let descriptionIndex=data.missingDescription?readIndex(/DESCRIPTION_INDEX\s*=\s*(\d+)/i):null;

// Selector is advisory. If it fails to return a valid index, n8n chooses the
// closest-to-target candidate already sorted by the hard validator.
if(data.missingTitle&&(!Number.isInteger(titleIndex)||!data.validTitleCandidates?.[titleIndex])) titleIndex=0;
if(data.missingDescription&&(!Number.isInteger(descriptionIndex)||!data.validDescriptionCandidates?.[descriptionIndex])) descriptionIndex=0;

const title=data.missingTitle?data.validTitleCandidates?.[titleIndex]:data.existingLineTitle;
const description=data.missingDescription?data.validDescriptionCandidates?.[descriptionIndex]:data.existingLineDescription;
const segmenter=new Intl.Segmenter('th',{granularity:'grapheme'});
const count=(v)=>[...segmenter.segment(String(v??'').trim())].length;
const valid=
  (!data.missingTitle||(Boolean(title)&&data.validTitleCandidates.includes(title)&&count(title)>=24&&count(title)<=60)) &&
  (!data.missingDescription||(Boolean(description)&&data.validDescriptionCandidates.includes(description)&&count(description)>=50&&count(description)<=90));
if(!valid){
  return [{json:{...data,state:'error',stage:'selector',errorCategory:'selector-contract-violation',errorMessage:'Selected candidate failed final n8n validation'}}];
}
return [{json:{...data,state:'success',stage:'selector',lineTitle:title,lineDescription:description,errorCategory:null,errorMessage:null}}];

