const base=$('เตรียมงาน LINE').item.json;
const responses=[
  $('Ollama · Improve A').item.json,
  $('Ollama · Improve B').item.json
];
const segmenter=new Intl.Segmenter('th',{granularity:'grapheme'});
const count=v=>[...segmenter.segment(String(v??'').trim())].length;
const clean=v=>String(v??'').replace(/\s+/g,' ').trim();
const banned=['รับประกันผลตอบแทน','รับประกันกำไร','รับประกันอนุมัติ','รับประกันเคลมผ่าน','รับประกันความคุ้มครอง','การันตีผลตอบแทน','การันตีกำไร','การันตีอนุมัติ','การันตีเคลมผ่าน','การันตีความคุ้มครอง','รับรองผลตอบแทน','รับรองกำไร','รับรองอนุมัติ','รับรองเคลมผ่าน','รับรองความคุ้มครอง','ไม่ขาดทุน','ไม่มีความเสี่ยง','ผลตอบแทนแน่นอน','อนุมัติแน่นอน','เคลมผ่านแน่นอน','คุ้มครองทุกกรณี','จ่ายแน่นอน','ห้ามพลาด','ด่วน','ก่อนสาย','ความลับ','ช็อก','ทัก LINE','LINE Official Account','CCPun','สนใจคุย','มาวางแผน'];
const identifier=/(?:^|\D)0\d{8,9}(?:\D|$)|[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}|(?:^|\D)\d{13}(?:\D|$)/i;
const dangling=/(?:[,;:/\-–—]|(?:\s|^)(?:และ|หรือ|ที่|ซึ่ง|เพื่อ|โดย|กับ|จาก|ของ|ใน|ให้|ว่า|เมื่อ|เพราะ|รวมถึง|ดังนี้))$/u;
const old=base.existingLineTitle+' '+base.existingLineDescription;
function valid(title,description){
  const joined=title+' '+description;
  const numbers=joined.match(/[0-9๐-๙]+/g)??[];
  return count(title)>=24&&count(title)<=60
    &&count(description)>=50&&count(description)<=90
    &&!banned.some(x=>joined.includes(x))
    &&!identifier.test(joined)
    &&!dangling.test(title)&&!dangling.test(description)
    &&numbers.every(x=>old.includes(x))
    &&(title!==base.existingLineTitle||description!==base.existingLineDescription);
}
const candidates=[];
for(const response of responses){
  if(response?.error||response?.done_reason==='length') continue;
  try{
    const parsed=JSON.parse(String(response?.message?.content??''));
    const lineTitle=clean(parsed.lineTitle);
    const lineDescription=clean(parsed.lineDescription);
    if(valid(lineTitle,lineDescription)) candidates.push({lineTitle,lineDescription});
  }catch{}
}
candidates.sort((x,y)=>
  Math.abs(count(x.lineTitle)-40)+Math.abs(count(x.lineDescription)-68)
  -Math.abs(count(y.lineTitle)-40)-Math.abs(count(y.lineDescription)-68)
);
const best=candidates[0];
return [{json:best
  ? {...base,state:'success',stage:'improve-validated',lineTitle:best.lineTitle,lineDescription:best.lineDescription,candidateStats:{attempts:responses.length,valid:candidates.length},errorCategory:null,errorMessage:null}
  : {...base,state:'error',stage:'improve-validation',candidateStats:{attempts:responses.length,valid:0},errorCategory:'model-output-invalid',errorMessage:'No safe complete improved LINE pair passed validation'}
}];

const data=$json;
const finishedAt=new Date().toISOString();
const elapsedMs=Math.max(0,Date.now()-(Date.parse(data.startedAt)||Date.now()));
return [{json:{...data,status:'error',stage:data.stage || 'error',finishedAt,elapsedMs,errorCategory:data.errorCategory || 'line-copy-failed',errorMessage:data.errorMessage || 'LINE copy generation failed'}}];
